  "date": "2023-12-23",
  "url": "http://minquan.gov.cn/bmxxgk/zrzyj/fdzdgknr37/ghjh37/gzgh17/content_7902",
  "source": "minquan.gov.cn_民权县人民政府",
  "category": "政府官方通报",
  "levels": [],
